changeSet.sql:
DROP INDEX idx_review_job_retention;
CREATE INDEX idx_review_job_retention ON review_job (completed_at, id)
WHERE status IN ('COMPLETED', 'FAILED', 'TIMED_OUT', 'CANCELLED') AND processing_status IN ('DONE', 'FAILED');

